    public void testDivide_NaNResult() {
        // Case 1: This is NaN
        Complex nan = new Complex(Double.NaN, Double.NaN);
        Complex c1 = new Complex(1.0, 1.0);
        assertTrue("Result should be NaN if dividend is NaN", c1.divide(nan).isNaN());

        // Case 2: Divisor is NaN
