    @Test
    public void testDivide_BothInfinite() {
        Complex inf = new Complex(Double.POSITIVE_INFINITY, Double.POSITIVE_INFINITY);
        // Should not return ZERO because !isInfinite() fails
        Complex result = inf.divide(inf);
        // Result will likely be NaN or follow the math logic below
        assertTrue(result.isNaN() || !result.equals(Complex.ZERO));
    }






