import org.apache.commons.math.util.MathUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class Complex_divide_TriageGen0Test {

    private static final double EPSILON = 1e-10;











    @Test
    public void testDivide_BranchSmallReal() {
        // Branch: FastMath.abs(c) < FastMath.abs(d)
        // divisor.getReal() = 1, divisor.getImaginary() = 10
        Complex dividend = new Complex(10.0, 10.0);
        Complex divisor = new Complex(1.0, 10.0);

        Complex result = dividend.divide(divisor);

        // (10+10i) / (1+10i) = [(10*1 + 10*10) / (1^2 + 10^2)] + i[(10*1 - 10*1) / 101]
        // = 110/101 + i(0)
        assertEquals(110.0/101.0, result.getReal(), EPSILON);
        assertEquals(0.0, result.getImaginary(), EPSILON);
    }




}

