public class Complex_divide_TriageGen0Test {

    private static final double EPSILON = 1e-10;













    @Test
    public void testDivide_BranchLargeReal() {
        // Branch: FastMath.abs(c) >= FastMath.abs(d)
        // divisor.getReal() = 10, divisor.getImaginary() = 1
        Complex dividend = new Complex(10.0, 10.0);
        Complex divisor = new Complex(10.0, 1.0);

        Complex result = dividend.divide(divisor);

        // (10+10i) / (10+i) = [10*(1-10) + 10] / [10*(1-10) + 10] ... wait, let's use standard formula
        // (10+10i)(10-i) / (100+1) = (100 - 10i + 100i + 10) / 101 = 110/101 + 90i/101
        assertEquals(110.0/101.0, result.getReal(), EPSILON);
        assertEquals(90.0/101.0, result.getImaginary(), EPSILON);
    }


}

