        // Tests the 'else' branch where abs(c) == abs(d)
        Complex dividend = new Complex(2.0, 2.0);
        Complex divisor = new Complex(3.0, 3.0);
        Complex result = dividend.divide(divisor);

        assertEquals(2.0/3.0, result.getReal(), EPSILON);
        assertEquals(2.0/3.0, result.getImaginary(), EPSILON);
    }
